fails = []

def check(s, ref, tag):
    # indexing / pop bounds / slices
    n = len(ref)
    for i in range(-n-4, n+4):
        try: got = s[i]
        except IndexError: got = 'IDXERR'
        try: exp = ref[i]
        except IndexError: exp = 'IDXERR'
        if got != exp:
            fails.append(('getitem', tag, i, got, exp, list(s), ref)); return True
    fresh = IndexedSet(ref)
    bounds = [None] + list(range(-n-4, n+5))
    for a in bounds:
        for b in bounds:
            for st in (None, 1, 2, 3, -1, -2):
                try: got = list(s[a:b:st])
                except Exception as e: got = f'EXC {type(e).__name__}'
                if got != list(fresh[a:b:st]):
                    fails.append(('slice_fresh', tag, (a,b,st), got, list(fresh[a:b:st]), list(s), ref)); return True
                if (st is None or st > 0) and got != ref[a:b:st]:
                    fails.append(('slice_list', tag, (a,b,st), got, ref[a:b:st], list(s), ref)); return True
    return False

ops = ['add','remove','discard','pop','clear','reverse','sort','update','difference_update','intersection_update','symmetric_difference_update','isub','iand','ixor','ior','append_via_slice']
for trial in range(400):
    s = IndexedSet()
    ref = []
    for step in range(30):
        op = random.choice(ops)
        other = [random.randrange(10) for _ in range(random.randrange(5))]
        try:
            if op == 'add':
                v = random.randrange(10); s.add(v)
                if v not in ref: ref.append(v)
            elif op == 'remove':
                if not ref: continue
                v = random.choice(ref); s.remove(v); ref.remove(v)
            elif op == 'discard':
                v = random.randrange(10); s.discard(v)
                if v in ref: ref.remove(v)
            elif op == 'pop':
                if not ref: continue
                if random.random() < 0.5:
                    got = s.pop(); exp = ref.pop()
                else:
                    i = random.randrange(-len(ref), len(ref))
                    got = s.pop(i); exp = ref.pop(i)
                if got != exp:
                    fails.append(('pop_inrange', op, got, exp, list(s), ref)); break
            elif op == 'clear':
                s.clear(); ref = []
            elif op == 'reverse':
                s.reverse(); ref = ref[::-1]
            elif op == 'sort':
                s.sort(); ref = sorted(ref)
            elif op == 'update':
                s.update(other)
                for v in other:
                    if v not in ref: ref.append(v)
            elif op == 'difference_update':
                s.difference_update(other)
                ref = [v for v in ref if v not in other]
            elif op == 'intersection_update':
                s.intersection_update(other)
                ref = [v for v in ref if v in other]
            elif op == 'symmetric_difference_update':
                s.symmetric_difference_update(other)
                nref = list(ref)
                for v in other:
                    if v in nref: nref.remove(v)
                    else: nref.append(v)
                ref = nref
            elif op == 'isub':
                s -= IndexedSet(other); ref = [v for v in ref if v not in other]
            elif op == 'iand':
                s &= IndexedSet(other); ref = [v for v in ref if v in other]
            elif op == 'ixor':
