    s = IndexedSet(base)
    for r in rem:
        s.remove(r)
    ref = [x for x in base if x not in rem]
    tag = f'removed={rem}'
    check(list(s) == ref, f'{tag}: iteration {list(s)} != {ref}')

    n = len(ref)
    # index checks over generous range
    for i in range(-n-5, n+5):
        try:
            got = s[i]
