            got = 'RAISED'
        expected = ref[i] if -n <= i < n else 'RAISED'
        check(got == expected, f'{tag}: s[{i}] = {got!r}, expected {expected!r}')

    # slices: forward slices must match list(s); all slices must match fresh set
    fresh = IndexedSet(ref)
    bounds = [None, -12, -9, -5, -1, 0, 1, 2, 5, 9, 12, 20]
    for a, b, c in itertools.product(bounds, repeat=3):
        try:
            got = list(s[a:b:c])
