        # vs fresh set for every step
        try:
            exp_fresh = list(fresh[a:b:c])
        except Exception as e:
            exp_fresh = f'{type(e).__name__}:{e}'
        check(got == exp_fresh, f'{tag}: fresh-compare s[{a}:{b}:{c}] = {got}, expected {exp_fresh}')

    # pop checks: pop every in-range index, out-of-range must raise before mutating
    for i in list(range(-n, n)) + [-n-1, -n-5, n, n+3]:
        s2 = IndexedSet(base)
