                    try: exp = oracle(val, binary, gnu, fmt)
                    except Exception as ex: exp = f"EXC:{type(ex).__name__}:{ex}"
                    if act != exp:
                        fails.append((fmt, binary, gnu, val, act, exp))
print("total fails", len(fails))
