    // 1.0.0-1 -> 2.0.0
    if (!lowVersion.patch && !lowVersion.minor) {
      return 'major'
    }

    // Otherwise compare the two versions: the highest level that differs
    // between them is the level of the change. Checking whether the high
    // version's own parts are non-zero would misreport e.g.
    // 3.4.6-2 -> 3.5.2 as a patch, even though the minor changed.

    if (highVersion.major !== lowVersion.major) {
      return 'major'
    }

    if (highVersion.minor !== lowVersion.minor) {
      return 'minor'
    }

    if (highVersion.patch !== lowVersion.patch) {
      return 'patch'
    }

    // The high version is the release of the low version's prerelease, so the
    // level is the highest part of the shared version that is set:
    // 1.2.3-1 -> 1.2.3 is a patch, 1.2.0-1 -> 1.2.0 a minor,
    // 1.0.0-1 -> 1.0.0 a major

    if (highVersion.patch) {
      return 'patch'
    }

    if (highVersion.minor) {
      return 'minor'
    }

    // bumping major/minor/patch all have same result
    return 'major'
  }

  // add the `pre` prefix if we are going to a prerelease version
  const prefix = highHasPre ? 'pre' : ''

  if (v1.major !== v2.major) {
    return prefix + 'major'
  }

  if (v1.minor !== v2.minor) {
    return prefix + 'minor'
  }

  if (v1.patch !== v2.patch) {
    return prefix + 'patch'
  }

