            # pop
            sp = build(p.IndexedSet, n, rem)
            sf = build(f.IndexedSet, n, rem)
            # reference list pop
            refpop = ref[:]
            expected_exc = None
            expected_val = None
            if idx is None:
                if refpop:
                    expected_val = refpop.pop()
                else:
                    expected_exc = IndexError
            else:
                # normalize like list does
                norm = idx
                if norm < 0: norm += len(refpop)
                if 0 <= norm < len(refpop):
                    expected_val = refpop.pop(norm)
                else:
                    expected_exc = IndexError
            # pristine
            try:
                if expected_exc:
                    sp.pop(idx)
                    p_res = 'NO_RAISE'
                else:
                    v = sp.pop(idx)
                    ok = (v == expected_val) and (list(sp) == refpop)
                    p_res = 'OK' if ok else 'WRONG'
            except IndexError:
                p_res = 'RAISED' if not expected_exc else 'OK'
            except Exception as e:
                p_res = 'OTHER_EXC'
            # fixed
            try:
                if expected_exc:
                    sf.pop(idx)
                    f_res = 'NO_RAISE'
                else:
                    v = sf.pop(idx)
                    ok = (v == expected_val) and (list(sf) == refpop)
                    f_res = 'OK' if ok else 'WRONG'
            except IndexError:
                f_res = 'RAISED' if not expected_exc else 'OK'
            except Exception as e:
                f_res = 'OTHER_EXC'

            if f_res == 'OK' and p_res != 'OK':
                get_real_only += 1
            elif p_res == 'OK' and f_res != 'OK':
                fixed_wrong_only += 1
                if len(examples_fixed_wrong) < 20:
                    examples_fixed_wrong.append(('pop', n, rem, idx, p_res, f_res, expected_val))
            elif p_res != 'OK' and f_res != 'OK':
                both_wrong += 1
            else:
                both_correct += 1

print(f'pop: fixed-correct-pristine-wrong={get_real_only}, fixed-wrong-pristine-correct={fixed_wrong_only}, both-wrong={both_wrong}, both-correct={both_correct}')
print('examples where fixed is WRONG but pristine OK:')
