const ids = ['0', '7', '4821', '9e1d', '7f3c', 'a7f3', 'rc', '1x', '07', '1-2', 'nightly', 'beta', '0', '123', '1a2b3c']
const comps = ['1', '2', '0', '01', '12', '2024', '4821', '1'.repeat(17), '007']
const suffixes = ['', '/x', ' build 12', 'x', 'xyz', ' (2024)', '.5', '-beta', '+meta', ' 42', '/', '.nightly.7f3c', '-nightly.7f3c', '+b.1']

const gen = () => {
  if (rnd(3) === 0) {
    // pure junk
    const alpha = '0123456789abcxyz.-+/ v'
    let s = ''
    const len = 3 + rnd(25)
    for (let i = 0; i < len; i++) s += pick(alpha.split(''))
    return s
  }
  const ncomp = 1 + rnd(4)
  let s = rnd(4) === 0 ? 'v' : ''
  const parts = []
  for (let i = 0; i < ncomp; i++) parts.push(pick(comps))
  s += parts.join('.')
  if (rnd(2) === 0) {
    const nid = 1 + rnd(3)
    const ids2 = []
    for (let i = 0; i < nid; i++) ids2.push(pick(ids))
    s += '-' + ids2.join('.')
    if (rnd(3) === 0) s += '+' + pick(ids) + (rnd(2) ? '.' + pick(ids) : '')
  } else if (rnd(4) === 0) {
    s += '+' + pick(ids)
  }
  s += pick(suffixes)
  return s
}

const core = (v) => v ? v.version.split('-')[0].split('+')[0] : null
const pre = (v) => { if (!v) return null; const m = v.version.match(/-([0-9A-Za-z.-]+)/); return m ? m[1] : null }
const bld = (v) => { if (!v) return null; const m = v.version.match(/\+([0-9A-Za-z.-]+)/); return m ? m[1] : null }

const cat = { newNullOldVal: [], coreDiff: [], preDropped: [], preDiffer: [], buildDiffer: [], newValOldNull: [] }

for (let i = 0; i < 6000; i++) {
